import csv
import json
import os

def load_codebooks(directory):
    codebooks = {}
    for filename in os.listdir(directory):
        if filename.startswith('codebook_') and filename.endswith('.csv'):
            product_id = filename.split('_')[1].split('.')[0]
            with open(os.path.join(directory, filename), 'r', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                codebooks[product_id] = list(reader)
    return codebooks

def normalize_reason(text, codebook, confidence_threshold=0.5):
    segments = text.split('，')
    normalized = []
    for i, segment in enumerate(segments, start=1):
        best_match = None
        best_score = 0
        for entry in codebook:
            keywords = entry['keywords_examples'].split(', ')
            for keyword in keywords:
                if keyword in segment:
                    score = 1.0  # Simple match, can be improved with more sophisticated scoring
                    if score > best_score:
                        best_match = entry
                        best_score = score
        if best_score >= confidence_threshold:
            normalized.append({
                'segment_id': f'{record_id}-S{i}',
                'span_text': segment,
                'pred_code': best_match['code'],
                'pred_label': best_match['standard_label'],
                'confidence': best_score,
                'rationale': f"Matched keyword: {best_match['keywords_examples']}"
            })
        else:
            normalized.append({
                'segment_id': f'{record_id}-S{i}',
                'span_text': segment,
                'pred_code': 'UNKNOWN',
                'pred_label': '',
                'confidence': 0.1,
                'rationale': 'No direct match in the codebook.'
            })
    return normalized

def process_logs(logs_path, codebooks, output_path):
    with open(logs_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        records = []
        for row in reader:
            global record_id
            record_id = row['record_id']
            product_id = row['product_id']
            if product_id in codebooks:
                normalized = normalize_reason(row['raw_reason_text'], codebooks[product_id])
                records.append({
                    'record_id': record_id,
                    'product_id': product_id,
                    'station': row['station'],
                    'engineer_id': row['engineer_id'],
                    'raw_reason_text': row['raw_reason_text'],
                    'normalized': normalized
                })
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump({'records': records}, f, ensure_ascii=False, indent=2)

# Load codebooks
codebooks = load_codebooks('data/')

# Process logs and write solution.json
process_logs('data/test_center_logs.csv', codebooks, 'solution.json')
EOF"}}

